INSERT OR REPLACE INTO products (id, category, look, price_now, price_old, default_size, active, sort, availability) VALUES ('stul-todo-soft', 'plastic-chairs', 'stul-todo-soft', 264000, 0, 0, 1, 5, 'unknown');
