INSERT OR REPLACE INTO products (id, category, look, price_now, price_old, default_size, active, sort, availability) VALUES ('stol-taper-rotang-135', 'tables', 'stol-taper-rotang-135', 954000, 0, 0, 1, 11, 'unknown');
